def transform(grid):
    out = [row[:] for row in grid]
    h = len(out)
    if not h:
        return out
    w = len(out[0])

    # Complete one-cell gaps enclosed by the same color in horizontal bars,
    # then extend the gap color upward until the ray reaches existing color.
    gaps = []
    for r in range(h):
        for c in range(1, w - 1):
            color = grid[r][c - 1]
            if color != 0 and grid[r][c] == 0 and grid[r][c + 1] == color:
                gaps.append((r, c, color))
    for r, c, color in sorted(gaps):
        out[r][c] = color
        rr = r - 1
        while rr >= 0 and out[rr][c] == 0:
            out[rr][c] = color
            rr -= 1

    # Bottom vertical bars continue upward through empty cells, stopping at
    # the first horizontal/object cell they encounter.
    for c in range(w):
        color = grid[h - 1][c]
        if color == 0:
            continue
        top = h - 1
        while top >= 0 and grid[top][c] == color:
            top -= 1
        rr = top
        while rr >= 0 and out[rr][c] == 0:
            out[rr][c] = color
            rr -= 1
    return out
